== Node
model Node {
  id               String        @id @default(cuid())
  name             String        @unique
  pveNode          String // Proxmox node name (e.g. ns5002569)
  apiUrl           String // https://host:8006
  tokenId          String
  tokenSecret      String
  publicIp         String
  bridge           String        @default("vmbr1")
  subnetPrefix     String        @default("10.20.0.") // /24 NAT subnet prefix
  ipStart          Int           @default(100)
  ipEnd            Int           @default(250)
  sshPortStart     Int           @default(20000)
  sshPortEnd       Int           @default(29999)
  natChain         String        @default("NXEON_FWD")
  storageNvme      String        @default("vmdata")
  storageHdd       String        @default("vmdata-hdd")
  capacityRamMB    Int           @default(56000)
  // What the platform actually PAYS the infra provider (OVH/Hetzner/etc) to
  // rent this physical box each month — admin-entered, not derived from
  // anything else. Null (not 0) until an operator fills it in: a real node
  // is never free, so 0 would misreport "unconfigured" as "no cost". Purely
  // a cost/margin-visibility figure for /admin/nodes — never read by the
  // scheduler or billing engine.
  monthlyCostCents Int?
  isPrimary        Boolean       @default(false)
  enabled          Boolean       @default(true)
  status           NodeStatus    @default(ONLINE)
  provider         NodeProvider  @default(OVH)
  // Provider's own datacenter code (e.g. "sgp1", "fsn1") — a plain validated
  // string, not an enum: see lib/node-regions.ts's NODE_REGIONS/REGION_LABELS
  // for the same "fast-changing categorical value, validated in code not the
  // DB" convention this schema already uses for StaffGrant.area.
  region           String        @default("sgp1")
  // The provider's OWN identifier for this physical box — OVH's "service
  // name" (e.g. "ns5002569.ip-51-79-162.net") or Hetzner's server number
  // (e.g. "2769362") — distinct from `pveNode` (Proxmox's own node name) and
  // `apiUrl`/`tokenId`/`tokenSecret` (the Proxmox API credentials). Needed by
  // lib/dedicated-ip.ts's per-node provider branch to make the right
  // OVH/Hetzner REST calls for THIS node's IP pool specifically. Nullable —
  // only required for a node that actually pools dedicated IPs.
  providerServerId String?
  // Node-agent (Class-B fixes: NAT sync, cloud-init snippet write, dnat-check —
  // see docs/DOCUMENTATION.md's "Multi-node synergy" for the full design). The
  // agent is the CALLEE; the worker on the primary is the CALLER, so unlike
  // Server.rootPasswordEnc's peers this must be DECRYPTABLE, not hashed — the
  // primary has to actually present the token on every request, the same
  // direction as `tokenSecret` above (also plaintext) but encrypted at rest
  // via lib/crypto-box.ts, since AUTH_SECRET-derived encryption was already
  // the established pattern for "a secret the app must read back" (rootPasswordEnc,
  // sourcePasswordEnc, anthropicKeyEnc) and tokenSecret predates it. Null on
  // the primary (which never runs the agent) and on any node onboarded before
  // Phase 3 shipped, until it's rotated in.
  agentTokenEnc    String?
  // Port the agent listens on for this node. A field, not a hardcoded
  // constant, so a node whose default port is already taken can be onboarded
  // without a code change.
  agentPort        Int           @default(8943)
  lastSeenAt       DateTime?
  createdAt        DateTime      @default(now())
  servers          Server[]
  dedicatedIps     DedicatedIp[]

  // Distinct from `enabled` — a disabled node drops off scheduling AND out of
  // most admin surfaces (it's meant for a node that's genuinely gone/retired).
  // This is narrower: "keep this node fully visible and its existing servers
  // running, just stop landing NEW provisions on it" — e.g. a node running
  // hot that shouldn't take more load without being torn out of the fleet.
  // Read by lib/node-capacity.ts scheduleNode(); the admin Infrastructure page
  // toggles it directly. Default true so every existing node behaves exactly
== Server
model Server {
  id                    String              @id @default(cuid())
  uptimeDays            ServerUptimeDaily[]
  name                  String
  label                 String? // customer-facing nickname (rename)
  // Set when this order arrived via a partner deep link (?ref=kodely on
  // /dashboard/deploy, captured by PartnerSourceCapture). Null for every direct
  // Nxeon order. Gates the webhook notify in worker/index.ts on provision success.
  partnerSource         String?
  // Globally unique across the ENTIRE fleet (VPS, game server, NxCloud alike) —
  // not just per-account. Before this constraint, every checkout path that left
  // the field blank silently handed out the same literal default ("web-01" for
  // VPS; "<family>-<rand>" for game servers, which could still collide), and
  // nothing stopped a customer from typing an already-used name either. A
  // hostname-keyed support/ops lookup (scripts/recover-errored-server.mjs) then
  // had no way to tell two same-named customers apart and grabbed the wrong
  // one's row — surfacing one customer's SSH port/status while working a
  // different customer's ticket (2026-09-24 incident, hsw901013@gmail.com).
  // Always write this through lib/hostname.ts's resolveUniqueHostname(), which
  // normalizes (trim+lowercase, matching HostingHostnameClaim's convention) and
  // auto-suffixes on collision instead of failing checkout or lying to the next
  // lookup. See scripts/find-duplicate-hostnames.ts / dedupe-hostnames.ts for
  // resolving pre-existing duplicates before this constraint can be applied
  // (prod currently has one: 7 servers literally named "web-01").
  hostname              String              @unique
  // Every hostname this server was EVER known as, oldest first, populated ONLY
  // by an admin-initiated rename of an EXISTING server (currently just
  // scripts/dedupe-hostnames.ts — ordinary checkout/admin-create paths write
  // `hostname` once at creation and never touch it again, so they never
  // append here). Exists because Invoice/WalletTransaction rows have no FK to
  // Server — every charge site instead embeds the hostname AT THE TIME OF
  // CHARGE in the record's `description` (see lib/server-spend.ts's own doc
  // comment for the full list of call sites and lib/actions-billing.ts's
  // `regenerateMissingInvoices`). A rename after those records were written
  // leaves them holding a hostname the server no longer has, so any
  // description-substring match keyed off the CURRENT hostname alone silently
  // stops finding them. Found live 2026-09-25: a real dedupe run on
  // 2026-09-24 renamed 6 duplicate "web-01" servers, which blanked their
  // "Total Spent" column on /admin/servers to "—" even though every one of
  // them has real, unbroken PAID invoice history. `resolveServerLifetimeSpendCents`
  // and `regenerateMissingInvoices` both match against `hostname` OR any
  // entry here so a rename can never again sever an existing record from the
  // server that earned it.
  previousHostnames    String[]            @default([])
  vmid                  Int?                @unique
  status                ServerStatus        @default(PENDING)
  ipAddress             String?             @unique
  sshPort               Int?                @unique
  // GUEST SSH PORT OVERRIDE (2026-09-30) — for a DEDICATED-IP server only.
  // connectionTarget() (lib/sftp.ts) has always assumed a dedicated-IP guest's
  // sshd listens on port 22 and ignored `sshPort` entirely for that case (that
  // field is the NAT-mapped external port for non-dedicated servers, a
  // different concept, and globally @unique — not safe to repurpose). A
  // customer who reconfigures their own guest's sshd to a non-standard port
  // (e.g. 2222) silently breaks every platform SSH feature — panel Files,
  // firewall sync, backups — with no way to tell it the new port. Found live
  // on a real HIGH-priority ticket (web-01-pvm4, 2026-09-30): customer moved
  // to port 2222 + key-only auth, firewall sync retried 3x and failed, Files
  // timed out; `nc` confirmed :22 closed and :2222 open, and the server's own
  // management key authenticated fine once dialed at :2222 directly. NULL
  // (the default, and every dedicated-IP server before this) means "assume
  // port 22" — connectionTarget() falls back with `?? 22`, so this column
  // changes behavior for nobody until explicitly set.
  guestSshPort          Int?
  rootPassword          String?
  rootPasswordEnc       String?
  // MANAGEMENT SSH KEY (2026-09-26) — a per-server ed25519 keypair, generated at
  // provision time (or backfilled via scripts/backfill-ssh-management-keys.ts for
  // servers that already existed), whose PUBLIC half is pushed into the guest's
  // authorized_keys. lib/ssh-exec.ts's withServerSsh tries this key BEFORE the
== Job
model Job {
  id        String    @id @default(cuid())
  type      JobType
  status    JobStatus @default(QUEUED)
  payload   Json?
  error     String?
  progress  Int       @default(0) // 0..100 live task progress (backups/restores)
  step      String? // human-readable current step, e.g. "Creating archive… 42%"
  attempts  Int       @default(0)
  serverId  String?
  server    Server?   @relation(fields: [serverId], references: [id], onDelete: Cascade)
  createdAt DateTime  @default(now())
  updatedAt DateTime  @updatedAt
  /// Set by the worker's atomic claim on the job's FIRST run (a retry keeps the
  /// original). `startedAt - createdAt` is the queue wait a customer actually
  /// experienced — the latency metric lib/job-metrics.ts reports. Null for
  /// rows that predate 2026-10-01.
  startedAt  DateTime?
  /// Set when the job reaches a terminal status (DONE/FAILED). `finishedAt -
  /// startedAt` is the run time, inclusive of retries.
  finishedAt DateTime?

  // The claim loop's hot query is `status = QUEUED ORDER BY createdAt`; the
  // metrics helper slices by (type, finishedAt). Both additive.
  @@index([status, createdAt])
  @@index([type, finishedAt])
}
== PortForward
model PortForward {
  id         String @id @default(cuid())
  serverId   String
  server     Server @relation(fields: [serverId], references: [id], onDelete: Cascade)
  publicPort Int    @unique
  guestPort  Int
  protocol   String @default("tcp")
}
== EmailLog
model EmailLog {
  id         String    @id @default(cuid())
  toEmail    String
  subject    String
  template   String? // template key (welcome, receipt, ...)
  html       String // rendered HTML, secrets redacted — see the model comment
  status     String    @default("SENT") // SENT | FAILED
  error      String?
  userId     String?
  createdAt  DateTime  @default(now())
  // Open/click tracking. `html` above already carries the tracking pixel +
  // rewritten link URLs (lib/mailer.ts sendMail), and the pixel/redirect routes
  // under app/api/track/email/[id]/... update these fields as events arrive.
  openedAt   DateTime?
  openCount  Int       @default(0)
  clickedAt  DateTime?
  clickCount Int       @default(0)
  // Real destination URLs, indexed positionally — app/api/track/email/[id]/
  // click/[idx] looks one up here to redirect. Anchors whose original href
  // carried a bearer secret (token/code/key/…, see SECRET_QUERY_PARAM in
  // lib/email-render.ts) are deliberately excluded from both this array AND
  // click-rewriting entirely: the whole point of that redaction is that a
  // secret must never gain a second, more casually-queryable home, and this
  // column — read by a plain unauthenticated GET — would be exactly that.
  links      Json?
  // Retry classification (see lib/critical-email-retry.ts, worker/critical-
  // email-retry.ts). `kind` mirrors the `NotifyKind` (lib/prefs.ts) passed to
  // `sendMail()`, if any — this is what lets the retry sweep find a FAILED row
  // whose kind is CRITICAL (payment_failed, provision_ready, suspension, ...)
  // without re-deriving the original template context. Null for sends that
  // omitted `kind` (most PRODUCT/no-preference sends) and for any row written
  // before this column existed.
  kind       String?
  // Count of automatic resend attempts the retry sweep has made against THIS
  // row. Bounded by MAX_RETRIES_PER_EMAIL. A resend attempt itself writes its
  // OWN EmailLog row (like any other send), but that new row is written
  // without `kind` — see the sweep's doc comment — so it can never become a
  // fresh retry root; this counter is what actually bounds the whole chain.
  retryCount Int       @default(0)
}
== ServerMemSample
model ServerMemSample {
  id         String   @id @default(cuid())
  serverId   String
  ts         DateTime @default(now())
  usedBytes  BigInt
  totalBytes BigInt

  @@index([serverId, ts])
}
== OutreachQueueItem
model OutreachQueueItem {
  id        String    @id @default(cuid())
  email     String
  fullName  String
  game      String
  channelUrl String?
  country   String?
  subscribers String?
  /// QUEUED | SENDING | SENT | FAILED | SKIPPED (admin skipped it, never sent)
  status    String    @default("QUEUED")
  error     String?
  createdAt DateTime  @default(now())
  sentAt    DateTime?
  // ---- campaign engine (2026-10-01; all additive/nullable so the 97 rows that
  // predate it keep working — worker/index.ts adopts orphans into the default
  // "Legacy creator queue" campaign, see lib/outreach/campaign-core.ts).
  campaignId String?
  campaign   OutreachCampaign? @relation(fields: [campaignId], references: [id], onDelete: Cascade)
  /// Send order inside a campaign (lower first); ties break on createdAt.
  sortOrder  Int       @default(0)
  attempts   Int       @default(0)
  lastAttemptAt DateTime?
  /// SMTP Message-ID of the send, and the EmailLog row (open/click tracking).
  messageId  String?
  emailLogId String?
  /// Template actually used for this row (name snapshot) — shown in the admin UI.
  templateName String?
  events     OutreachEvent[]

  @@index([status, createdAt])
  @@index([campaignId, status, sortOrder])
  @@index([email])
}
