cd /opt/nxeon; S=/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/health; cat > $S/db1.ts <<'EOF'
import { PrismaClient } from "@prisma/client";
const p = new PrismaClient();
const j = (x:any)=>console.log(JSON.stringify(x,(k,v)=>typeof v==="bigint"?Number(v):v));
const q = async (t:string, sql:string)=>{ console.log("### "+t); try{ const r:any=await p.$queryRawUnsafe(sql); j(r);}catch(e:any){console.log("ERR",String(e.message).slice(0,200));}};
(async()=>{
await q("nodes",`select name,"pveNode","publicIp",enabled,status::text,"isPrimary","subnetPrefix","lastSeenAt","capacityRamMB" from "Node" order by name`);
await q("server status by node",`select n.name node, s.status::text, count(*) c from "Server" s left join "Node" n on n.id=s."nodeId" group by 1,2 order by 1,2`);
await q("job fail by type 7d",`select type::text, count(*) c from "Job" where status='FAILED' and "updatedAt">now()-interval '7 days' group by 1 order by 2 desc`);
await q("job totals 7d",`select type::text,status::text,count(*) from "Job" where "createdAt">now()-interval '7 days' group by 1,2 order by 1,2`);
await q("top errors 7d",`select left(regexp_replace(coalesce(error,''),'[0-9a-f]{20,}|[0-9]+','N','g'),140) e, type::text, count(*) c from "Job" where status='FAILED' and "updatedAt">now()-interval '7 days' group by 1,2 order by 3 desc limit 15`);
await q("stuck running >30m",`select j.id,type::text,attempts,"updatedAt","createdAt",s.hostname from "Job" j left join "Server" s on s.id=j."serverId" where j.status='RUNNING' and j."updatedAt"<now()-interval '30 minutes'`);
await q("queued old",`select type::text,count(*),min("createdAt") from "Job" where status='QUEUED' group by 1`);
await q("running jobs now",`select type::text,count(*) from "Job" where status='RUNNING' group by 1`);
await q("servers problem states",`select s.hostname, s.status::text, n.name node, s.vmid, s."gameVariant", now()-s."updatedAt" age, left(coalesce(s."provisionError",''),100) err, s."expiresAt" from "Server" s left join "Node" n on n.id=s."nodeId" where s.status in ('PROVISIONING','ERROR','SUSPENDED','PENDING','REINSTALLING','DELETING') order by s.status, s."updatedAt"`);
await q("expired but running",`select s.hostname,s.status::text,s."expiresAt",s."autoRenew",s."dunningStage",s."billingGraceUntil",s."isFree" from "Server" s where s.status in ('RUNNING','STOPPED') and s."expiresAt"<now() order by "expiresAt"`);
await q("dunning stuck",`select s.hostname,s.status::text,s."dunningStage",s."dunningNextAt",s."expiresAt" from "Server" s where s."dunningStage">0 and s.status<>'SUSPENDED' order by "dunningNextAt"`);
await q("negative wallets",`select id,"balanceCents" from "User" where "balanceCents"<0`);
await q("wallet sum vs tx mismatch",`select u.id, u."balanceCents", coalesce(t.s,0) txsum from "User" u left join (select "userId", sum("amountCents") s from "WalletTransaction" group by 1) t on t."userId"=u.id where u."balanceCents"<>coalesce(t.s,0) limit 10`);
await q("email fail 24h",`select template, left(coalesce(error,''),100) err, count(*) from "EmailLog" where status='FAILED' and "createdAt">now()-interval '24 hours' group by 1,2 order by 3 desc limit 15`);
await q("email totals 24h",`select status,count(*) from "EmailLog" where "createdAt">now()-interval '24 hours' group by 1`);
await q("auto-renew failures 7d",`select s.hostname, count(*) from "AuditLog" a join "Server" s on a."targetId"=s.id where a."createdAt">now()-interval '7 days' and (a.action ilike '%renew%fail%' or a.action ilike '%renew_fail%') group by 1`);
await q("audit action names renew",`select action,count(*) from "AuditLog" where "createdAt">now()-interval '7 days' and action ilike '%renew%' group by 1`);
await q("outreach queue",`select status,count(*),max("sentAt") from "OutreachQueueItem" group by 1`);
await q("outreach err",`select left(coalesce(error,''),120),count(*) from "OutreachQueueItem" where status='FAILED' group by 1`);
await q("freemc",`select status,count(*) from "FreeMinecraftServer" group by 1`);
await q("freemc events 24h",`select * from "FreeMinecraftEvent" order by 1 desc limit 0`);
await q("free public",`select slug,status,host,port from "FreePublicServer"`);
await q("healthsample latest",`select distinct on (component) component,status,"latencyMs",left(coalesce(detail,''),80),ts from "HealthSample" order by component, ts desc`);
await q("healthsample non-ok 24h",`select component,status,count(*) from "HealthSample" where ts>now()-interval '24 hours' and status<>'ok' group by 1,2`);
await q("nodealert open",`select "nodeName",dimension,severity,pct,left(detail,100),"createdAt" from "NodeAlert" where status<>'RESOLVED' and "resolvedAt" is null order by "createdAt" desc limit 20`);
await q("status incidents open",`select component,severity,title,"startedAt" from "StatusIncident" where "resolvedAt" is null`);
await q("errorlog 24h top",`select source,left(message,100) m,sum(count) c from "ErrorLog" where "lastSeen">now()-interval '24 hours' and not resolved group by 1,2 order by 3 desc limit 15`);
await q("uptime flapping 3d",`select s.hostname, sum(u.up) up, sum(u.total) tot, round(100.0*sum(u.up)/nullif(sum(u.total),0),1) pct from "ServerUptimeDaily" u join "Server" s on s.id=u."serverId" where u.date>now()-interval '3 days' group by 1 having sum(u.up)<sum(u.total)*0.97 order by pct limit 20`);
await q("dedicated ips",`select d.address,d.status::text,d.purpose::text,n.name node,s.hostname from "DedicatedIp" d join "Node" n on n.id=d."nodeId" left join "Server" s on s.id=d."serverId" order by n.name,d.address`);
await q("ssl certs",`select domain,status,"expiresAt",left(coalesce("lastError",''),80) from "SslCertificate" where "expiresAt"<now()+interval '30 days' or status not in ('ACTIVE','ISSUED') order by "expiresAt" limit 20`);
await q("hosting accts",`select status::text,count(*) from "HostingAccount" group by 1`);
await q("custom domains",`select hostname,"customDomain","customDomainVerified" from "Server" where "customDomain" is not null limit 20`);
await q("hosting domains",`select "primaryDomain",status::text,"sslActive","serveHttpsOk" from "HostingAccount" limit 20`);
await q("websites domains",`select domain,ssl,status from "Website" limit 30`);
await q("dup vmid in db",`select n.name, s.vmid, count(*) from "Server" s join "Node" n on n.id=s."nodeId" where s.vmid is not null group by 1,2 having count(*)>1`);
await q("stripe webhook errs",`select source,left(message,100),sum(count) from "ErrorLog" where (source ilike '%stripe%' or message ilike '%webhook%') and "lastSeen">now()-interval '7 days' group by 1,2 order by 3 desc limit 10`);
await q("pending ext payments",`select count(*), min("createdAt") from "PendingExternalPayment"`);
await p.$disconnect();
})();
EOF
cp $S/db1.ts ./.h1.ts 2>/dev/null; rm -f ./.h1.ts; npx tsx $S/db1.ts 2>&1 | cut -c1-2500

