cd /opt/nxeon; S=/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/health; cat > $S/pve.ts <<'EOF'
import { PrismaClient } from "/opt/nxeon/node_modules/@prisma/client";
import { pveForNode } from "/opt/nxeon/lib/proxmox";
const p = new PrismaClient();
(async()=>{
const nodes = await p.node.findMany({orderBy:{name:"asc"}});
const servers = await p.server.findMany({select:{hostname:true,vmid:true,status:true,nodeId:true,node:{select:{name:true}},isFree:true,expiresAt:true}});
const out:any={};
for(const n of nodes){
  const r:any={};
  try{
    const c=pveForNode(n as any);
    const st=await c.get(`/nodes/${n.pveNode}/status`);
    r.mem={used:Math.round(st.memory.used/2**20),total:Math.round(st.memory.total/2**20)};
    r.swap={used:Math.round(st.swap.used/2**20),total:Math.round(st.swap.total/2**20)};
    r.root={used:Math.round(st.rootfs.used/2**30),total:Math.round(st.rootfs.total/2**30)};
    r.load=st.loadavg; r.cpus=st.cpuinfo?.cpus; r.uptimeDays=Math.round(st.uptime/86400); r.kver=st.kversion?.slice(0,40); r.pve=st.pveversion;
    const vms=await c.get(`/nodes/${n.pveNode}/qemu`);
    const cts=await c.get(`/nodes/${n.pveNode}/lxc`).catch(()=>[]);
    r.vms=vms.map((v:any)=>({id:v.vmid,name:v.name,st:v.status,maxmemMB:Math.round(v.maxmem/2**20),tpl:v.template?1:0,diskGB:Math.round(v.maxdisk/2**30)}));
    r.cts=cts.length;
    const stor=await c.get(`/nodes/${n.pveNode}/storage`);
    r.storage=stor.map((s:any)=>({s:s.storage,type:s.type,content:s.content,usedGB:Math.round((s.used||0)/2**30),totalGB:Math.round((s.total||0)/2**30),active:s.active}));
    r.backups={};
    for(const s of stor.filter((s:any)=>(s.content||"").includes("backup")&&s.active)){
      try{ const b=await c.get(`/nodes/${n.pveNode}/storage/${s.storage}/content`,{content:"backup"});
        const latest:any={}; for(const x of b){ if(!latest[x.vmid]||x.ctime>latest[x.vmid]) latest[x.vmid]=x.ctime; }
        r.backups[s.storage]={count:b.length,sizeGB:Math.round(b.reduce((a:number,x:any)=>a+x.size,0)/2**30),newestAgeH:b.length?Math.round((Date.now()/1000-Math.max(...b.map((x:any)=>x.ctime)))/3600):null,perVmAgeH:Object.fromEntries(Object.entries(latest).map(([k,v]:any)=>[k,Math.round((Date.now()/1000-v)/3600)]))};
      }catch(e:any){r.backups[s.storage]="ERR "+String(e.message).slice(0,80);}
    }
    const tasks=await c.get(`/nodes/${n.pveNode}/tasks`,{limit:300,errors:1,typefilter:"vzdump"}).catch(()=>[]);
    r.failedBackupTasks=tasks.filter((t:any)=>t.status&&t.status!=="OK").slice(0,10).map((t:any)=>({vm:t.id,when:new Date(t.starttime*1000).toISOString(),status:String(t.status).slice(0,80)}));
  }catch(e:any){ r.error=String(e.message).slice(0,200); }
  out[n.name]=r;
}
// compare
const cmp:string[]=[];
for(const n of nodes){ const r=out[n.name]; if(!r.vms) continue;
  const dbs=servers.filter(s=>s.nodeId===n.id);
  const dbIds=new Set(dbs.map(s=>s.vmid));
  for(const v of r.vms){ if(v.tpl) continue; if(v.id>=9000&&v.id<10000) continue; const d=dbs.find(s=>s.vmid===v.id);
    if(!d) cmp.push(`${n.name}: VM ${v.id} ${v.name} (${v.st}) NOT IN DB`);
    else if((d.status==="RUNNING")!==(v.st==="running")) cmp.push(`${n.name}: VM ${v.id} ${v.name} pve=${v.st} db=${d.status} (${d.hostname})`);
  }
  for(const d of dbs){ if(d.vmid && !r.vms.find((v:any)=>v.id===d.vmid)) cmp.push(`${n.name}: DB server ${d.hostname} vmid ${d.vmid} (${d.status}) MISSING in pve`); }
}
// names across nodes
const byName:any={}; for(const n of nodes){ for(const v of out[n.name].vms||[]){ (byName[v.name]??=[]).push(`${n.name}:${v.id}:${v.st}`);} }
const dups=Object.entries(byName).filter(([k,v]:any)=>v.length>1&&!/^tpl-/.test(k));
const byId:any={}; for(const n of nodes){ for(const v of out[n.name].vms||[]){ if(v.id<9000)(byId[v.id]??=[]).push(`${n.name}:${v.name}`);} }
const idc=Object.entries(byId).filter(([k,v]:any)=>v.length>1);
const tpl:any={}; for(const n of nodes){ tpl[n.name]=(out[n.name].vms||[]).filter((v:any)=>v.id>=9000&&v.id<9100).map((v:any)=>v.id).join(","); }
console.log(JSON.stringify({out,cmp,dups,idc,tpl},null,0));
await p.$disconnect();
})();
EOF
