    r.failedBackupTasks=tasks.filter((t:any)=>t.status&&t.status!=="OK").slice(0,10).map((t:any)=>({vm:t.id,when:new Date(t.starttime*1000).toISOString(),status:String(t.status).slice(0,80)}));
  }catch(e:any){ r.error=String(e.message).slice(0,200); }
