  for(const v of r.vms){ if(v.tpl) continue; if(v.id>=9000&&v.id<10000) continue; const d=dbs.find(s=>s.vmid===v.id);
    if(!d) cmp.push(`${n.name}: VM ${v.id} ${v.name} (${v.st}) NOT IN DB`);
    else if((d.status==="RUNNING")!==(v.st==="running")) cmp.push(`${n.name}: VM ${v.id} ${v.name} pve=${v.st} db=${d.status} (${d.hostname})`);
  }
  for(const d of dbs){ if(d.vmid && !r.vms.find((v:any)=>v.id===d.vmid)) cmp.push(`${n.name}: DB server ${d.hostname} vmid ${d.vmid} (${d.status}) MISSING in pve`); }
}
// names across nodes
const byName:any={}; for(const n of nodes){ for(const v of out[n.name].vms||[]){ (byName[v.name]??=[]).push(`${n.name}:${v.id}:${v.st}`);} }
const dups=Object.entries(byName).filter(([k,v]:any)=>v.length>1&&!/^tpl-/.test(k));
const byId:any={}; for(const n of nodes){ for(const v of out[n.name].vms||[]){ if(v.id<9000)(byId[v.id]??=[]).push(`${n.name}:${v.name}`);} }
